svg.script:
//
(function() {
  function init(el) {
    var threshold = 0.5;
    var debounce = 150;
    var steps = []; for (var s = 0; s <= 20; s++) steps.push(s / 20);
    function pxRatio(i) {
      var t = i.boundingClientRect, v = i.intersectionRect;
      if (!t || !t.height || !v) return i.intersectionRatio;
      var vp = Math.min(window.innerHeight || Infinity, i.rootBounds ? i.rootBounds.height : Infinity);
      if (!isFinite(vp)) vp = t.height;
      var d = Math.min(t.height, vp);
      return d > 0 ? v.height / d : i.intersectionRatio;
    }
    var finished = false;
    el.addEventListener("animationend", function() { finished = true; });
    var open = false, timer = 0;
    function pxOpen() {
      timer = 0; if (open) return; open = true;
      if (finished) { finished = false; el.classList.remove("px-anim-enabled", "px-anim-playing"); el.getBoundingClientRect(); }
      el.classList.add("px-anim-enabled", "px-anim-playing");
    }
    function pxClose() {
      if (timer) { clearTimeout(timer); timer = 0; }
      if (!open) return; open = false; el.classList.remove("px-anim-playing");
    }
    new IntersectionObserver(function(e) { e.forEach(function(i) {
      var r = i.isIntersecting ? pxRatio(i) : 0;
      if (r > 0 && r >= threshold) { if (!open && !timer) { timer = debounce > 0 ? setTimeout(pxOpen, debounce) : (pxOpen(), 0); } }
      else if (r <= 0) { pxClose(); }
      else if (!open && timer) { clearTimeout(timer); timer = 0; }
    }); }, { threshold: steps }).observe(el);
  }
  var el = document.currentScript.closest('svg');
  (el ? [el] : document.querySelectorAll("#_px_3g09tpke")).forEach(init);
})();
//
